// === Tab: mySketch ===
// OPC SETUP
// You can easily create dynamic variables to use in your sketch.
// Read full documentation at https://github.com/msawired/OPC
OPC.title('Circle Settings', 'Changes various circle attributes');

// Creates a variable "radius" that can be controlled via a slider, with default value 250
// OPC.slider('radius', 500);	//short version. min/max auto-calculated
// OPC.slider('radius', 500, 0, 1000, 10); //min/max/step defined

OPC.slider( //or you can provide an object with full attributes
	{
		name: 'radius',
		value: 500,
		min: 0,
		max: 1000,
		step: 10,
		label: 'Radius Max',
		description: 'Maximum radius of the circle'
	}
);


// OPC.toggle('has_stroke', true); //toggle short version
OPC.toggle({ //object version
	name: 'has_stroke',
	value: true,
	label: 'Border Enabled?',
	description: 'Adds a border on the circles'
});

// simple select (dropdown) version with array
// OPC.select('circles', [5,4,3,2,1]);

// advanced select with key->value pairs. Key is used as label in UI.
OPC.select('circles', {
	"A Lot": 5,
	"Few": 3,
	"One": 1
});

// add a simple label with a value and description. You can change the value later.
OPC.label('Frame Rate', 0, 'Higher value = smoother animation');

OPC.title('Other Settings');

OPC.color('bg_color', '#333'); //native color selector

// Some color palette options to choose from
let myPalettes = [
	["#eabfcb", "#c191a1", "#a4508b", "#5f0a87", "#2f004f"],
	["#c3dfe0", "#bcd979", "#9dad6f", "#7d6d61", "#5e574d"],
	["#4464ad", "#a4b0f5", "#f58f29", "#7d4600", "#466995"]
];
OPC.palette('palette', myPalettes);


// text input
OPC.text('My Title', '', 'Enter Title');

OPC.bezier('Animation'); //generates an easing function that you can customize via UI

// for buttons, see ButtonPressed and ButtonReleased functions below
//by default, first argument is used as button label
// OPC.button('pauseButton');	//simple
OPC.button('pauseButton', 'Pause'); //label separate	

// You can also control these via OSC devices through running an OSC server on localhost
// read more here: https://github.com/msawired/OPC#osc-support
// OPC.setOSC('ws://localhost', 8081);


// REST OF THE SKETCH BELOW
let paused = false;
let freakDistanceMax = 120;
let freak = 0;
let currentRadius = radius;


function setup() {
	createCanvas(windowWidth, windowHeight);
	strokeWeight(5);
}

function draw() {

	if (!paused) {
		let eased = Animation(frameCount % 100 / 100);
		currentRadius = radius * eased;
	}
	window['Frame Rate'] = frameRate().toFixed(0);
	background(bg_color);
	strokeWeight(15);
	has_stroke ? stroke('#f5f5f5') : noStroke();
	fill(palette[0]);
	circle(width / 5 * 0.5, height / 2, currentRadius);

	if (circles >= 2) {
		fill(palette[1]);
		circle(width / 5 * 1.5, height / 2, currentRadius);
	}
	if (circles >= 3) {
		fill(palette[2]);
		circle(width / 5 * 2.5, height / 2, currentRadius);
	}
	if (circles >= 4) {
		fill(palette[3]);
		circle(width / 5 * 3.5, height / 2, currentRadius);
	}
	if (circles >= 5) {
		fill(palette[4]);
		circle(width / 5 * 4.5, height / 2, currentRadius);
	}

	fill('#333');
	textAlign('center');
	textSize(100);
	text(window['My Title'], width / 2, height / 2 + 30);
}

//parameterChanged function is used every time a parameter is updated.
function parameterChanged(variableName, newValue) {
	// print(variableName,newValue);
}

//BUTTON FUNCTIONS
//buttonPressed function is used every time a button is pressed.
function buttonReleased(variableName) {
	//you can check variableName if you have multiple buttons
	switch (variableName) {
		case 'pauseButton':
			paused = !paused;
			pauseButton = paused ? 'Resume' : 'Pause';
			break;
		case 'Reset':
			radius = 0;
			break;
	}
}

function keyPressed() {
	//you can remotely collapse/expand the configurator sa well
	switch (key) {
		case 'c':
			OPC.collapse();
			break;
		case "e":
			OPC.expand();
			break;
	}
}

